#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Test CameraApiId::kGetCameras (3100) — camera catalog via CameraClient.GetCameras().
Requires booster_camera (CameraApiTopic DDS RPC) online.
"""

import sys
import unittest

import booster_robotics_sdk_python as br

from common import (
    create_camera_client,
    init_channel_factory,
    parse_network_interface,
    parse_robot_name,
    print_device_info,
    usage,
)

API_ID = int(br.CameraApiId.kGetCameras)


class TestGetCameras(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.net_if = parse_network_interface(sys.argv)
        cls.robot_name = parse_robot_name(sys.argv)
        init_channel_factory(cls.net_if)
        cls.client = create_camera_client(cls.robot_name)

    def test_get_cameras_via_client(self) -> None:
        info = self.client.GetCameras()
        if info.kind == br.DeviceInfoKind.kUnknown:
            info.kind = br.DeviceInfoKind.kCamera
        self.assertEqual(info.kind, br.DeviceInfoKind.kCamera)
        print_device_info("GetCameras (CameraClient)", API_ID, info)
        self.assertIn("cameras", info.to_json_str())

    def test_get_cameras_via_raw_api_id(self) -> None:
        resp = self.client.SendApiRequestWithResponse(
            br.CameraApiId.kGetCameras, ""
        )
        self.assertTrue(resp.body)
        info = br.DeviceInfo.from_json_str(resp.body)
        info.kind = br.DeviceInfoKind.kCamera
        print_device_info(
            "SendApiRequestWithResponse(kGetCameras)", API_ID, info
        )


def main() -> int:
    if len(sys.argv) > 1 and sys.argv[1] in ("-h", "--help"):
        usage(__file__)
        return 0
    suite = unittest.defaultTestLoader.loadTestsFromTestCase(TestGetCameras)
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    return 0 if result.wasSuccessful() else 1


if __name__ == "__main__":
    sys.exit(main())
